import{_ as e,o as l,c as a,ag as o}from"./chunks/framework.DXGyWiRo.js";const q=JSON.parse('{"title":"知识点4：数据安全与隐私保护","description":"","frontmatter":{"title":"知识点4：数据安全与隐私保护"},"headers":[],"relativePath":"high-school-it/knowledge-4.md","filePath":"high-school-it/knowledge-4.md"}'),_={name:"high-school-it/knowledge-4.md"};function r(i,t,n,s,h,d){return l(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="知识点4-数据安全与隐私保护" tabindex="-1">知识点4：数据安全与隐私保护 <a class="header-anchor" href="#知识点4-数据安全与隐私保护" aria-label="Permalink to &quot;知识点4：数据安全与隐私保护&quot;">​</a></h1><h2 id="一、数据安全防护方法" tabindex="-1">一、数据安全防护方法 <a class="header-anchor" href="#一、数据安全防护方法" aria-label="Permalink to &quot;一、数据安全防护方法&quot;">​</a></h2><h3 id="数据脱敏" tabindex="-1">数据脱敏 <a class="header-anchor" href="#数据脱敏" aria-label="Permalink to &quot;数据脱敏&quot;">​</a></h3><p><strong>定义</strong>：在不影响数据分析结果的前提下，对敏感数据进行变形处理，保护个人隐私不被泄露。</p><p><strong>书中的例子</strong>：</p><ul><li>对姓名、学生证号、手机号码等字段进行处理：姓名打码（如&quot;张**&quot;）、手机号隐藏中间位（如&quot;138*****678&quot;）</li></ul><p><strong>通俗理解 - 快递单</strong>：</p><blockquote><p>快递单上的隐私号码：</p><ul><li>真实号码：13812345678</li><li>脱敏后：138*****678</li></ul><p>——快递员能联系到你，但旁人看不到完整号码</p></blockquote><h3 id="数据加密" tabindex="-1">数据加密 <a class="header-anchor" href="#数据加密" aria-label="Permalink to &quot;数据加密&quot;">​</a></h3><p><strong>定义</strong>：将数据转换成密文，只有拥有密钥的人才能解密还原。</p><p><strong>通俗理解 - 保险箱</strong>：</p><blockquote><p>加密就像把文件锁进保险箱，只有持有钥匙（密钥）的人才能打开阅读。</p></blockquote><h3 id="数据备份" tabindex="-1">数据备份 <a class="header-anchor" href="#数据备份" aria-label="Permalink to &quot;数据备份&quot;">​</a></h3><p><strong>定义</strong>：复制数据并存储在安全位置，以防数据丢失或损坏。</p><hr><h2 id="二、身份认证" tabindex="-1">二、身份认证 <a class="header-anchor" href="#二、身份认证" aria-label="Permalink to &quot;二、身份认证&quot;">​</a></h2><ul><li><strong>单因素认证</strong>：用户名 + 密码</li><li><strong>双因素认证（2FA）</strong>：需要两种不同类别的身份验证凭证（如密码属于&quot;你知道什么&quot; + 短信验证码属于&quot;你拥有什么&quot;）</li><li><strong>其他认证方式</strong>：人脸识别、指纹识别、手机短信验证码、USB Key 等</li></ul><h2 id="三、总结" tabindex="-1">三、总结 <a class="header-anchor" href="#三、总结" aria-label="Permalink to &quot;三、总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">概念</th><th style="text-align:left;">核心要点</th><th style="text-align:left;">一句话记忆</th></tr></thead><tbody><tr><td style="text-align:center;">数据脱敏</td><td style="text-align:left;">变形处理，保持数据可用</td><td style="text-align:left;">&quot;打码了但还能用&quot;</td></tr><tr><td style="text-align:center;">数据加密</td><td style="text-align:left;">转为密文，需要密钥</td><td style="text-align:left;">&quot;锁起来，要有钥匙&quot;</td></tr><tr><td style="text-align:center;">数据备份</td><td style="text-align:left;">复制保存，防灾备</td><td style="text-align:left;">&quot;多存一份，以防万一&quot;</td></tr></tbody></table><hr><h2 id="四、真题" tabindex="-1">四、真题 <a class="header-anchor" href="#四、真题" aria-label="Permalink to &quot;四、真题&quot;">​</a></h2><p><strong>1.（2025-01，综合题三）</strong> 小申在登录系统时，采用的是用户名+密码的身份认证方式。请列举两种其他的身份认证方式。（填空题，6分）</p><p>①_______________________________________</p><p>②_______________________________________</p><p><strong>2.（2025-01，综合题三）</strong> 小申在测试专用教室预约系统时，发现没有用户注册功能。于是新增了用户注册模块，采用用户名+密码的认证方式，以下表述正确的是（ ）（单选题，2分）</p><ul><li>A. 注册成功后，用户无需审核就能使用系统所有功能</li><li>B. 注册时，用户名必须和密码保持一致</li><li>C. 注册时，用户名和密码必须符合该系统规范的安全要求</li><li>D. 注册成功后，不会改变该系统数据库中的数据</li></ul><p><strong>3.（2025-01，综合题四）</strong> 在不影响数据分析结果的前提下，对姓名、学生证号、手机号码等字段的数据进行了处理（如表所示），保护参观者的个人隐私不被泄露，这种数据安全防护方法是__________________（选填：数据加密/数据脱敏/数据备份）。（填空题，2分）</p><p><strong>4.（浦东新区2025，综合题三）</strong> 为了防止恶意刷票和账号盗用，学校信息中心在预约系统的家长登录环节引入了&quot;双因素认证（2FA）&quot;机制。双因素认证要求用户提供两种不同类别的身份验证凭证（如&quot;你知道什么&quot;、&quot;你拥有什么&quot;等）。以下登录验证方式中，真正属于双因素认证的是（ ）（单选题，2分）</p><ul><li>A. 家长输入预约时设定的用户名和登录密码</li><li>B. 家长输入登录密码后，再输入预约时填写的&quot;学生姓名&quot;进行二次验证</li><li>C. 家长输入登录密码后，通过绑定的手机接收并输入短信动态验证码方可登录</li><li>D. 家长输入手机号码后，系统向该手机发送一次性登录密码，家长输入该密码</li></ul><h3 id="答案" tabindex="-1">答案 <a class="header-anchor" href="#答案" aria-label="Permalink to &quot;答案&quot;">​</a></h3><ol><li>参考答案：① 人脸识别/指纹识别；② 手机短信验证码（其他合理答案均可）</li><li>C</li><li>数据脱敏</li><li>C（密码属于&quot;你知道什么&quot;，短信验证码属于&quot;你拥有什么&quot;；A、B、D均只用到单一类别凭证）</li></ol>',31)])])}const g=e(_,[["render",r]]);export{q as __pageData,g as default};
